window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-39701\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάφρευσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 243 na letra τ · nº geral 39701</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ταφρεία.</p></section></article>\n<article id=\"entry-dgp-39702\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταφρεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 244 na letra τ · nº geral 39702</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cavar um fosso. 〈τάφρος〉</p></section></article>\n<article id=\"entry-dgp-39703\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάφρη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 245 na letra τ · nº geral 39703</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">τάφρος. 〈θάπτω〉</p></section></article>\n<article id=\"entry-dgp-39704\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάφρος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 246 na letra τ · nº geral 39704</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fossa; fosso. 〈θάπτω〉</p></section></article>\n<article id=\"entry-dgp-39705\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταφών</h1><div class=\"entry-meta\"><span>DGP · ordem 247 na letra τ · nº geral 39705</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. τέθηπα.</p></section></article>\n<article id=\"entry-dgp-39706\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάχα</h1><div class=\"entry-meta\"><span>DGP · ordem 248 na letra τ · nº geral 39706</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 prontamente; rapidamente; depressa; logo 2 át. provavelmente; talvez 3 em respostas, é possível; ἴσως τάχα xen., τάχ᾽ ἂν ἴσως sóf., τάχα που luc. é bem possível ♦ ὡς τάχα conj. 4 át. logo que; desde que. 〈ταχύς〉</p></section></article>\n<article id=\"entry-dgp-39707\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάχει</h1><div class=\"entry-meta\"><span>DGP · ordem 249 na letra τ · nº geral 39707</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. de τάχος.</p></section></article>\n<article id=\"entry-dgp-39708\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχεῖ</h1><div class=\"entry-meta\"><span>DGP · ordem 250 na letra τ · nº geral 39708</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. de ταχύς.</p></section></article>\n<article id=\"entry-dgp-39709\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχεῖα</h1><div class=\"entry-meta\"><span>DGP · ordem 251 na letra τ · nº geral 39709</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de ταχύς.</p></section></article>\n<article id=\"entry-dgp-39710\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχέως</h1><div class=\"entry-meta\"><span>DGP · ordem 252 na letra τ · nº geral 39710</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. depressa; logo; prontamente; rapidamente.</p></section></article>\n<article id=\"entry-dgp-39711\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχθῆναι</h1><div class=\"entry-meta\"><span>DGP · ordem 253 na letra τ · nº geral 39711</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. pas. de τάσσω.</p></section></article>\n<article id=\"entry-dgp-39712\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχίνας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 254 na letra τ · nº geral 39712</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">animal ágil; lebre. 〈ταχύς〉</p></section></article>\n<article id=\"entry-dgp-39713\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάχιστα, τάχιστος, ταχίων</h1><div class=\"entry-meta\"><span>DGP · ordem 255 na letra τ · nº geral 39713</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ταχύς.</p></section></article>\n<article id=\"entry-dgp-39714\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάχος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 256 na letra τ · nº geral 39714</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 velocidade; rapidez; presteza: ὡς τάχεος εἶχεν ἕκαστος her. tão veloz quanto cada um podia, cada um com toda sua velocidade, ὡς εἶχον τάχους tuc. tão veloz quanto eles puderam, lit. o quanto eles tinham de velocidade ♦ adv. 2 às pressas; rapidamente; διὰ ou ἀπὸ τάχους, ἐν ou σὺν τάχει, εἰς ou κατὰ τάχος depressa, prontamente, ὅ τι τάχος ou ὅσον τάχος ou ᾖ τάχος tão veloz quanto possível, o mais prontamente possível.</p></section></article>\n<article id=\"entry-dgp-39715\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχύ</h1><div class=\"entry-meta\"><span>DGP · ordem 257 na letra τ · nº geral 39715</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ταχύς.</p></section></article>\n<article id=\"entry-dgp-39716\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχυάλωτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 258 na letra τ · nº geral 39716</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de que alguém se pode apoderar rapidamente; facilmente capturável. 〈ταχύ, ἀλίσκομαι〉</p></section></article>\n<article id=\"entry-dgp-39717\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχύδακρυς, υς, υ</h1><div class=\"entry-meta\"><span>DGP · ordem 259 na letra τ · nº geral 39717</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. υος pronto para chorar; de choro fácil. 〈ταχύ, δάκρυ〉</p></section></article>\n<article id=\"entry-dgp-39718\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχυεργία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 260 na letra τ · nº geral 39718</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">presteza para executar; diligência. 〈ταχύ, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-39719\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχυναυτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 261 na letra τ · nº geral 39719</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">navegar rapidamente. 〈ταχύ, ναύτης〉</p></section></article>\n<article id=\"entry-dgp-39720\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 262 na letra τ · nº geral 39720</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 apressar; acelerar 2 intr. apressar-se; agir rápido. 〈ταχύς〉</p></section></article>\n<article id=\"entry-dgp-39721\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχύπτερος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 263 na letra τ · nº geral 39721</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de asas rápidas; de voo rápido. 〈ταχύ, πτερόν〉</p></section></article>\n<article id=\"entry-dgp-39722\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχύπωλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 264 na letra τ · nº geral 39722</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de cavalos ágeis, epít. dos gregos. 〈ταχύς, πῶλος〉</p></section></article>\n<article id=\"entry-dgp-39723\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχύρρωστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 265 na letra τ · nº geral 39723</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de voo rápido. 〈ταχύ, ῥώομαι〉</p></section></article>\n<article id=\"entry-dgp-39724\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχύς, εῖα, ύ</h1><div class=\"entry-meta\"><span>DGP · ordem 266 na letra τ · nº geral 39724</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(comp. θάσσων, át. θάττων, jôn. ταχύτερος e ταχίων; superl. θάχιστος e θαχύτατος) 1 que anda, corre ou voa rapidamente; rápido; veloz, com ac. de rel. ou com inf.: ταχέες πόδες hom. pés ágeis, τ. ἰός ou ὀϊστός hom. flecha rápida, ταχεῖαι νῆες her. ou τριήρεις tuc. navios que navegam bem, bons veleiros, πόδας ταχύς hom. de pés ligeiros, θείειν ταχύς hom. pronto para correr, θάσσονας ἰρήκων ἵππους hom. cavalos mais velozes que falcões 2 que acontece ou sobrevém rapidamente; súbito (coisa): τ. ἅδῃς eur. morte rápida, τ. πόλεμος tuc. guerra que sobrevém rápidα ou subitamente, ταχεῖα φυγή tuc. fuga repentina 3 rápido; breve; curto: ταχεῖα διήγησις artt. narração concisa 4 apressado; precipitado: φρονεῖν ταχεῖς sóf. prontos para pensar, para conceber, ταχεῖς ἰέναι ἐς τοὺς πολέμους tuc. prontos para lançarem-se em guerras, διὰ ταχέων tuc., ἐκ ταχείας sóf. rapidamente, logo, ταχεῖ σὺν χρόνῳ sóf. em pouco tempo, τὴν ταχίστην her. o mais rapidamente possível ♦ ταχύ adv. 5 rapidamente: ταχὺ ἀπαλλάσσονται her. rapidamente elas vão embora ♦ θᾶσσον adv. comp. 6 mais rapidamente: após um rel., ou uma partíc., com sent. superl., ὅ τι θᾶσσον teócr. o mais rapidamente possível, ἐπειδὴ θᾶττον, ὅτε ou ὡς θᾶττον, ἐὰν ou ἢν θᾶττον logo que, assim que 7 de preferência; antes: οὔ· θᾶσσον ἂν τῆς πλεῖστον ἐχθίστης ἐμοὶ κλύοιμι sóf. não! antes ouviria minha pior inimiga ♦ τάχιστα adv. superl. 8 muito rapidamente; tão logo: ἀπαλλαγεὶς γὰρ αὐτῶν τάχιστα plut. logo que ele se libertou disso, ὡς ἂν δύνωμαι τ. ou ᾗ ἂν δύναμαι τ. xen. o mais rapidamente que eu puder, ὡς ἠδύνατο τ. ou ᾗ ἠδύνατο τ. xen. o mais prontamente que ele pudesse, ὡς ou ὅπως ou ὅσον ou ὅτι τάχιστα hom. o mais prontamente possível, ἐπεὶ ou ἐπειὰν ou ἐπὰν ou ἐπειδὰν ou ὅταν ou ὅπως ou ὡς τάχιστα logo que.</p></section></article>\n<article id=\"entry-dgp-39725\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχυτής, ῆτος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 267 na letra τ · nº geral 39725</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">velocidade; rapidez; agilidade. 〈ταχύς〉</p></section></article>\n<article id=\"entry-dgp-39726\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταώ</h1><div class=\"entry-meta\"><span>DGP · ordem 268 na letra τ · nº geral 39726</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. sing. de ταώς.</p></section></article>\n<article id=\"entry-dgp-39727\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταῴ</h1><div class=\"entry-meta\"><span>DGP · ordem 269 na letra τ · nº geral 39727</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nom. pl. de ταώς.</p></section></article>\n<article id=\"entry-dgp-39728\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάων</h1><div class=\"entry-meta\"><span>DGP · ordem 270 na letra τ · nº geral 39728</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. pl. dór. e eól. de ἡ pron. dem., ou de ἥ pron. rel.</p></section></article>\n<article id=\"entry-dgp-39729\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 271 na letra τ · nº geral 39729</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ταώς.</p></section></article>\n<article id=\"entry-dgp-39730\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταώνειος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 272 na letra τ · nº geral 39730</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de pavão. 〈ταῶν〉</p></section></article>\n<article id=\"entry-dgp-39731\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταώς, ώ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 273 na letra τ · nº geral 39731</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pavão.</p></section></article>\n<article id=\"entry-dgp-39732\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τε</h1><div class=\"entry-meta\"><span>DGP · ordem 274 na letra τ · nº geral 39732</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">partíc. enclít. 1 poét., valor dem. por isso; por essa razão: ὅς κε θεοῖς ἐπιπείθηται, μάλα τ᾽ ἔκλυον αὐτοῦ hom. aquele que sabe obedecer aos deuses, os deuses por conseguinte se comprazem em atendê-lo 2 na verdade, enfático em juramentos, pactos e ordens: ἦ τ᾽ ἐκέλευον hom. na verdade eles ordenavam ♦ conj. 3 e, une duas palavras ou duas orações ger. com outro τε, com καί, com μέν... δέ (nas construções μέν τε... δέ τε, μέν τε... δέ, μέν... δέ τε, μέν... τε) : ὃς Χρύσην ἀμφιβέβηκας Τενέδοιό τε ἶφι ἀνάσσεις hom. tu que proteges Crisa e que reinas soberano sobre Tênedos, πατὴρ ἀνδρῶν τε θεῶν τε hom. pai dos homens e dos deuses, δύσετό τ᾽ ἠέλιος σκιόωντο τε πᾶσαι ἀγυιαί hom. e o sol se deitou e todas as ruas se cobriram de sombra, διαστήτην Ἀτρείδης τε ἄναξ ἀνδρῶν καὶ δῖος Ἀχιλλεύς hom. puseram-se em desacordo o Atrida chefe de guerreiros e o divino Aquiles, κραιπνότερος μὲν γάρ τε νόος, λεπτὴ δέ τε μῆτις hom. de fato por um lado o espírito é muito ágil, por outro, a decisão é lenta.</p></section></article>\n<article id=\"entry-dgp-39733\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέ᾽</h1><div class=\"entry-meta\"><span>DGP · ordem 275 na letra τ · nº geral 39733</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">τεά em elisão.</p></section></article>\n<article id=\"entry-dgp-39734\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεά</h1><div class=\"entry-meta\"><span>DGP · ordem 276 na letra τ · nº geral 39734</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. n. de τεός.</p></section></article>\n<article id=\"entry-dgp-39735\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέγγω</h1><div class=\"entry-meta\"><span>DGP · ordem 277 na letra τ · nº geral 39735</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. τέγξω, aor. ἔτεγξα, perf. desus.; pas. aor. ἐτέγχθην) 1 molhar; regar; umedecer: δάκρυσι κόλ­πους τ. ésql. molhar de lágrimas as pregas da veste, τ. παρειάν sóf. molhar a face de lágrimas, τ. λόγον ψεύδει pínd. umedecer com mentira uma fala, tingir de falsidade uma fala 2 fazer correr: τ. δακρύων ἄχναν sóf. fazer correr um regato de lágrimas 3 deixar derreter; amolecer ♦ pas 4 ter os olhos marejados de lágrimas 5 correr; escoar; espalhar-se 6 fundir 7 deixar-se amolecer; deixar-se comover.</p></section></article>\n<article id=\"entry-dgp-39736\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τεγέα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 278 na letra τ · nº geral 39736</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tegeia, cidade da Arcádia.</p></section></article>\n<article id=\"entry-dgp-39737\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τεγεάτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 279 na letra τ · nº geral 39737</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">habitante ou originário de Tegeia; tegeata; tegeeu. 〈Τεγέα〉</p></section></article>\n<article id=\"entry-dgp-39738\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τεγεᾶτις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 280 na letra τ · nº geral 39738</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 de Tegeia; tegeeia ♦ ἡ Τεγεᾶτις 2 território de Tegeia. 〈Τεγέα〉</p></section></article>\n<article id=\"entry-dgp-39739\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τεγέη</h1><div class=\"entry-meta\"><span>DGP · ordem 281 na letra τ · nº geral 39739</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Τεγέα.</p></section></article>\n<article id=\"entry-dgp-39740\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τεγεητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 282 na letra τ · nº geral 39740</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. de Tegeia; tegeeu. 〈Τεγέα〉</p></section></article>\n<article id=\"entry-dgp-39741\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέγεος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 283 na letra τ · nº geral 39741</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">próximo ao teto; situado na parte superior da casa. 〈τέγος〉</p></section></article>\n<article id=\"entry-dgp-39742\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέγος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 284 na letra τ · nº geral 39742</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 teto (da casa, de cômodo) 2 parte coberta de uma casa ou de um cômodo, esp. nos andares superiores 3 morada; habitação 4 bordel.</p></section></article>\n<article id=\"entry-dgp-39743\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεθαλυῖα</h1><div class=\"entry-meta\"><span>DGP · ordem 285 na letra τ · nº geral 39743</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. perf. fem. de θάλλω.</p></section></article>\n<article id=\"entry-dgp-39744\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέθαμμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 286 na letra τ · nº geral 39744</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. pas. de θάπτω.</p></section></article>\n<article id=\"entry-dgp-39745\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεθάφαται</h1><div class=\"entry-meta\"><span>DGP · ordem 287 na letra τ · nº geral 39745</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. perf. pas. jôn. de θάπτω.</p></section></article>\n<article id=\"entry-dgp-39746\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεθέαμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 288 na letra τ · nº geral 39746</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. de θεάομαι.</p></section></article>\n<article id=\"entry-dgp-39747\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέθεικα, τέθειμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 289 na letra τ · nº geral 39747</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. at. e pas. de τίθημι.</p></section></article>\n<article id=\"entry-dgp-39748\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεθέληκα</h1><div class=\"entry-meta\"><span>DGP · ordem 290 na letra τ · nº geral 39748</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. de θέλω.</p></section></article>\n<article id=\"entry-dgp-39749\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέθηλα</h1><div class=\"entry-meta\"><span>DGP · ordem 291 na letra τ · nº geral 39749</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. de θάλλω.</p></section></article>\n<article id=\"entry-dgp-39750\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεθηλημένος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 292 na letra τ · nº geral 39750</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. perf. pas. jôn. de θάλλω.</p></section></article>\n<article id=\"entry-dgp-39751\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεθῆναι</h1><div class=\"entry-meta\"><span>DGP · ordem 293 na letra τ · nº geral 39751</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.1 pas. de τίθημι.</p></section></article>\n<article id=\"entry-dgp-39752\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέθηπα</h1><div class=\"entry-meta\"><span>DGP · ordem 294 na letra τ · nº geral 39752</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. com valor de pres. (part. τεθηπώς, m.-q.-perf. ép. ἐτεθήπεα com sent. de impf., aor.2 ἔταφον, part. ταφών) ser tomado de estupor ou de admiração; ficar atônito diante de algo ou alguém, ac.: τέθηπα ἀκούων her. estou estupefato de ouvir, οἱ τὸν πλοῦτόν σου τεθηπότες luc. os embasbacados diante de tua riqueza, ταφὼν δ᾽ ἀνόρουσε συβώτης hom. estupefato, o porqueiro levantou-se.</p></section></article>\n<article id=\"entry-dgp-39753\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέθλιμμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 295 na letra τ · nº geral 39753</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. pas. de θλίβω.</p></section></article>\n<article id=\"entry-dgp-39754\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέθναθι</h1><div class=\"entry-meta\"><span>DGP · ordem 296 na letra τ · nº geral 39754</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper. perf. sinc., τεθναίην opt. perf. sinc., τεθνάκοντι 3ª pl. perf. dór., τέθναμεν 1ª pl. perf. sinc., τεθνάμεν e τεθνάμεναι inf. perf. ép. sinc., τεθνάναι inf. perf. sinc., τεθναξοῦμαι fut. ant. dór., τεθνᾶσι 3ª pl. perf. sinc., τεθνάτω 3ª sing. imper. perf. sinc., τεθνεώς, n. τεθνεός part. perf., τέθνηκα perf., τεθνήξουμαι e τεθνήξω fut. ant., τεθνηώς part. perf. ép., de θνῄσκω.</p></section></article>\n<article id=\"entry-dgp-39755\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεθορεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 297 na letra τ · nº geral 39755</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 poét. de θρῴσκω.</p></section></article>\n<article id=\"entry-dgp-39756\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεθορυβημένως</h1><div class=\"entry-meta\"><span>DGP · ordem 298 na letra τ · nº geral 39756</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. tumultuadamente; em desordem. 〈θορυβέω〉</p></section></article>\n<article id=\"entry-dgp-39757\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέθραμμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 299 na letra τ · nº geral 39757</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. pas. de τρέφω.</p></section></article>\n<article id=\"entry-dgp-39758\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεθριπποβάτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 300 na letra τ · nº geral 39758</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) montado em quadriga; que dirige uma quadriga. 〈τέθριππος, βαίνω〉</p></section></article>\n<article id=\"entry-dgp-39759\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέθριππος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 301 na letra τ · nº geral 39759</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 atrelado com quatro cavalos (carro) 2 de quadrigas (combate) ♦ τὸ τέθριππον 3 quadriga. 〈τέτταρες, ἵππος〉</p></section></article>\n<article id=\"entry-dgp-39760\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεθριπποτροφέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 302 na letra τ · nº geral 39760</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">criar tiros de quatro cavalos. 〈τεθριπποτρόφος〉</p></section></article>\n<article id=\"entry-dgp-39761\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεθριπποτρόφος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 303 na letra τ · nº geral 39761</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que cria tiros de quatro cavalos para quadrigas. 〈τέθριππος, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-39762\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέθρυμμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 304 na letra τ · nº geral 39762</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. pas. de θρύπτω.</p></section></article>\n<article id=\"entry-dgp-39763\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεθρυμμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 305 na letra τ · nº geral 39763</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. molemente; de maneira efeminada.</p></section></article>\n<article id=\"entry-dgp-39764\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεΐν</h1><div class=\"entry-meta\"><span>DGP · ordem 306 na letra τ · nº geral 39764</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. e dór. = σοί.</p></section></article>\n<article id=\"entry-dgp-39765\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τείνω</h1><div class=\"entry-meta\"><span>DGP · ordem 307 na letra τ · nº geral 39765</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. τενῶ, aor. ἔτεινα, perf. τέτακα; pas. fut.ταθή­σομαι, aor. ἐτάθην, perf. τέταμαι) 1 distender; estender: ἐξ ἄντυγος ἡνία τείνας hom. distendendo as rédeas a partir do corrimão [do carro], ἐπ᾽Ἀλεξάνδρῳ τείνοντα πάλαι τόξον ésql. ao distender outrora o arco contra Alexandre, ξείνης μ᾽ ἐπὶ γούνατα χεῖρας ἀνάσσης δερκόμενοι τείνουσαν a.r. ao me verem a estender as mãos sobre os joelhos de uma rainha estrangeira 2 estender; desdobrar; espalhar: ὅτε τε Ζεὺς λαίλαπα τείνῃ hom. quando Zeus espalha uma tempestade, εἰ δὲ θεός περ ἶσον τείνειεν πολέμου τέλος hom. se um deus estendesse um resultado igual do combate [aos dois combatentes], i.e., se estendesse um empate, τεῖνε αὐδάν ésql. lança um grito 3 endereçar; apontar; visar algo, ac., contra alguém, dat. ou εἰς e ac.: ποίους ἰδιωτικοὺς λόγους ἐναντία τούτοις τεί­νοντας κρατήσειν; plat. que tipo de argumentos dirigidos individualmente contra essas pessoas [imaginas] que prevaleceria? καί μοι δοκεῖ Κέβης εἰς σὲ τείνειν τὸν λόγον plat. parece-me que Cebes dirige o discurso em tua direção, i.e., o discurso de Cebes visa a ti, ἐς τήνδ᾽Ἀχιλλεὺς ἐνδίκως τείνει φόνον; eur. com justiça Aquiles aponta a morte para esta [jovem], ἐπὶ Τροίᾳ τεῖναι τὰ θεῶν ἀμάχητα βέλη sóf. disparar contra Tróia as invencíveis flechas divinas 4 estender; alongar; prolongar: θαρσαλέαις τὸν μακρὸν τείνειν βίον ἐλπίσι ésql. com ousadas esperanças prolongar a longa vida, ὡς δὲ μὴ μακροὺς τείνω λόγους eur. para que eu não alongue demais o discurso, γύναι, μακρὰν ἔτεινας ésql. mulher, alongaste demais tua fala ♦ intr. 5 prolongar-se: τείνων χρόνος ésql. tempo que se alonga 6 estender-se na direção de: παρὰ λίμνην τὸ ὄρος τείνει her. o monte se estende junto do lago 7 tender para algo, εἰς, ἐπί, πρός e ac. 8 correr; abalar-se; tender: τενεῖς ὡς τὴν γυναῖκα καὶ τὰ παιδί᾽ οἴκαδε ar. correrás para casa, para junto da mulher e dos filhos 9 estar relacionado a; dizer respeito a alguém, εἰς e ac., ou a algo, πρός e ac.: ταῦτα ὦν πάντα ἐς σὲ νῦν τείνει her. é, portanto, a ti que agora tudo diz respeito, τοῦτο τοῦ ᾄσματος πρὸς τοῦτο τείνει plat. essa parte do poema diz respeito a isso 10 assemelhar-se a; tender para: ἐγγύς τι τείνειν τοῦ τεθνάναι ὁ μηδὲν φροντίζων τῶν ἡδονῶν plat. aquele que não se preocupa com os prazeres tende para o estar morto 11 esforçar-se; empenhar-se: τὸ μὴ τείνειν ἄγαν sóf. não se empenhar demais, i.e., não ser aferrado à sua opinião, não ser renitente ♦ méd. pas. 12 estender; estirar (pescoço, pés) 13 estender-se; estirar-se: ἵστια τέτατο hom. as velas estão estendidas, νύξ τέταται βροτοῖσιν hom. a noite se estendeu sobre os mortais, ὥς τε σκώληξ ἐπὶ γαίῃ κεῖτο ταθείς hom. como um verme, jazia estendido sobre a terra 14 prolongar-se: ἵπποισι τάθη δρόμος hom. os cavalos aumentaram a velocidade, τέτατο κρατερὴ ὑσμίνη hom. o combate aumentava em fúria, μάχη τέτατο πόλεμος τε hom. o combate e a luta se prolongavam.</p></section></article>\n<article id=\"entry-dgp-39766\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τείρεα</h1><div class=\"entry-meta\"><span>DGP · ordem 308 na letra τ · nº geral 39766</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só nom. e ac. (τά) astros celestes; constelações.</p></section></article>\n<article id=\"entry-dgp-39767\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τειρεσίας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 309 na letra τ · nº geral 39767</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, jôn., Τειρεσίης, -αο (ὁ) Tirésias, adivinho mítico de Tebas.</p></section></article>\n<article id=\"entry-dgp-39768\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τείρω</h1><div class=\"entry-meta\"><span>DGP · ordem 310 na letra τ · nº geral 39768</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf. at. e pas.) 1 (dor, desconforto) desgastar; consumir; esgotar; acabrunhar 2 comprimir muito.</p></section></article>\n<article id=\"entry-dgp-39769\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχεσιπλήτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 311 na letra τ · nº geral 39769</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">voc. τειχεσιπλῆτα (ὁ) destruidor de muralhas, epít. de Ares. 〈τεῖχος, πελάω〉</p></section></article>\n<article id=\"entry-dgp-39770\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 312 na letra τ · nº geral 39770</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. jôn. ἐτείχεον) 1 construir muro ou fortaleza 2 rodear de muros; fortificar, ac. 〈τεῖχος〉</p></section></article>\n<article id=\"entry-dgp-39771\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχήρης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 313 na letra τ · nº geral 39771</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 encerrado, enclausurado em muros 2 sitiado. 〈τεῖχος〉</p></section></article>\n<article id=\"entry-dgp-39772\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 314 na letra τ · nº geral 39772</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. át. τειχιῶ, aor. ἐτείχισα, perf. τετείχικα; pas. m.-q.-perf. ἐτετειχίσμην) 1 construir em forma de muralha ou para defender-se: τ. τεῖχος tuc. construir muros 2 rodear de muralhas; fortificar: λίθοις τε τὴν πόλιν τ. dem. fortificar a cidade com pedras ♦ méd. (fut. τειχιοῦμαι, aor. ἐτειχισάμην) 3 construir para sua defesa: τὸ ἔρυμα τῷ στρατοπέδῳ οὐκ ἂν ἐτειχίσαντο tuc. não teriam construído o muro de defesa para o acampamento 4 fortificar com muralha em defesa própria, ac. ♦ pas. 5 ser fortificado: ἀθανάτῳ δὲ τείχει τῷ Νείλῳ τετειχισμένην isócr. [região] fortificada pelo Nilo, muralha imortal, τὰ τετειχισμένα tuc. as partes da cidade fortificadas. 〈τεῖχος〉</p></section></article>\n<article id=\"entry-dgp-39773\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχιόεις, όεσσα, όεν</h1><div class=\"entry-meta\"><span>DGP · ordem 315 na letra τ · nº geral 39773</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cercado de muros, de muralhas. 〈τεῖχος〉</p></section></article>\n<article id=\"entry-dgp-39774\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 316 na letra τ · nº geral 39774</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muro de casa, de pátio. 〈τεῖχος〉</p></section></article>\n<article id=\"entry-dgp-39775\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τείχισις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 317 na letra τ · nº geral 39775</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">construção de muralha, de fortificação. 〈τειχίζω〉</p></section></article>\n<article id=\"entry-dgp-39776\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τείχισμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 318 na letra τ · nº geral 39776</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">obra de defesa; fortificação. 〈τειχίζω〉</p></section></article>\n<article id=\"entry-dgp-39777\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 319 na letra τ · nº geral 39777</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">τείχισις.</p></section></article>\n<article id=\"entry-dgp-39778\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχοδομία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 320 na letra τ · nº geral 39778</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">construção de muralha, de fortaleza. 〈τεῖχος, δέμω〉</p></section></article>\n<article id=\"entry-dgp-39779\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχολέτις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 321 na letra τ · nº geral 39779</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) destruidora das muralhas ou das fortificações de uma cidade. 〈τεῖχος, ὄλλυμι〉</p></section></article>\n<article id=\"entry-dgp-39780\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχομαχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 322 na letra τ · nº geral 39780</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 atacar fortificações; lançar-se ao assédio 2 atacar alguém, dat., como a uma muralha; tomar de assalto. 〈τεῖχος, μάχομαι〉</p></section></article>\n<article id=\"entry-dgp-39781\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχομαχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 323 na letra τ · nº geral 39781</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">combate nas muralhas ou em redor das muralhas; assédio a uma cidade. 〈τεῖχος, μάχομαι〉</p></section></article>\n<article id=\"entry-dgp-39782\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχοποιέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 324 na letra τ · nº geral 39782</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">construir fortificações. 〈τειχοποιός〉</p></section></article>\n<article id=\"entry-dgp-39783\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχοποιία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 325 na letra τ · nº geral 39783</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">construção de muralhas. 〈τειχοποιός〉</p></section></article>\n<article id=\"entry-dgp-39784\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχοποιός, οῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 326 na letra τ · nº geral 39784</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 construtor de muralha ♦ οἱ τειχοποιοί 2 em Atenas, inspetores das obras de fortificações. 〈τεῖχος, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-39785\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεῖχος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 327 na letra τ · nº geral 39785</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 muralha; muro: τείχη χαλκᾶ ésqn. muralhas de bronze, τ. δέμειν ou οἰκοδομεῖν construir um muro, τ. ἄγειν ou ἐλαύνειν levar adiante a construção de um muro; em Atenas, τὰ μακρὰ τείχη as Grandes Muralhas, linha de fortificação unindo a cidade ao Pireu 2 fortificação; fortaleza; forte 3 lugar fortificado; praça forte.</p></section></article>\n<article id=\"entry-dgp-39786\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχοφυλακέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 328 na letra τ · nº geral 39786</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">montar guarda nas muralhas, nas fortificações. 〈τειχοφύλαξ〉</p></section></article>\n<article id=\"entry-dgp-39787\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχοφύλαξ, ακος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 329 na letra τ · nº geral 39787</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">guardião de muralhas; sentinela. 〈τεῖχος, φύλαξ〉</p></section></article>\n<article id=\"entry-dgp-39788\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τειχύδριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 330 na letra τ · nº geral 39788</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequena fortificação. 〈τεῖχος〉</p></section></article>\n<article id=\"entry-dgp-39789\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τείως</h1><div class=\"entry-meta\"><span>DGP · ordem 331 na letra τ · nº geral 39789</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = τέως.</p></section></article>\n<article id=\"entry-dgp-39790\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέκε</h1><div class=\"entry-meta\"><span>DGP · ordem 332 na letra τ · nº geral 39790</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor.2, τεκέειν aor.2 inf., τεκεῖν inf. aor.2, τέκετο 3a sing. aor.2 méd., formas poét. de τίκτω.</p></section></article>\n<article id=\"entry-dgp-39791\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεκμαίρω</h1><div class=\"entry-meta\"><span>DGP · ordem 333 na letra τ · nº geral 39791</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐτέκμηρα) 1 dar um sinal determinante; determinar; indicar; fixar: τορῶς τέκμηρον, ὅ τι μ᾽ ἐπαμμένει παθεῖν ésql. determina, i.e., mostra-me claramente o que me resta padecer ♦ méd. (fut. τεκμαροῦμαι, aor. ἐτεκμηράμην) 2 designar; fixar; atribuir: ἄλλην ἡμῖν ὁδὸν τεκμήρατο Κίρκη hom. Circe nos fixou um outro caminho 3 indicar com segurança; fazer saber com precisão: εἰ δέ κε σίνηαι, τότε τοι τεκμαίρομ᾽ ὄλεθρον, νηί τε καὶ ἑτάροις hom. mas se houver infração, indico-te como certa a ruína, para tua nau e teus companheiros 4 reconhecer por indícios, por sinais: τ. ὄπα κούρης a.r. reconhecer a voz da mocinha 5 formar um juízo, uma opinião, a partir de indícios; conjeturar uma coisa, ac. ou or. inf., com base em outra, dat. ou ἀπό, ἐκ e gen.: ἔνιοι γράφουσιν καὶ λέγουσιν περὶ αὐτοῦ τεκμαιρόμενοι xen. alguns escrevem e falam a respeito dele [de Sócrates] baseados em conjeturas, ἔργῳ κοὐ λόγῳ τεκμαίρομαι ésql. baseio meu juízo em atos, não em palavras, τεκμαίρεσθαι τοῖσι νῦν ἔτι ἐοῦσι Πελασγῶν her. conjeturar com base nos indícios ainda existentes dos pelasgos, τ. τοῖς ἐμφανέσι τὰ μὴ γινωσκόμενα her. conjeturar, com base nas evidências, o que não se conhece, τ. τὰ καινὰ τοῖς πάλαι sóf. conjeturar o novo com base no antigo, πόθεν τοῦτο τεκμαίρει; plut. onde buscas indícios para tais conjecturas? τ. τοῦτο οὕτως ἕξειν ἐκ τοῦδε xen. conjeturar que será assim a partir disso. 〈τέκμαρ〉</p></section></article>\n<article id=\"entry-dgp-39792\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέκμαρ,</h1><div class=\"entry-meta\"><span>DGP · ordem 334 na letra τ · nº geral 39792</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. τέκμωρ indecl. (τό) 1 marco como limite 2 termo; fim; objetivo 3 linha de demarcação 4 sinal de reconhecimento ou de garantia 5 garantia; penhor 6 sinal; indício 7 Medic. sintoma.</p></section></article>\n<article id=\"entry-dgp-39793\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέκμαρσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 335 na letra τ · nº geral 39793</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conjetura; suposição; julgamento por conjetura 2 indício; fundamento de uma suposição 3 olhar perspicaz para adivinhar. 〈τεκμαίρω〉</p></section></article>\n<article id=\"entry-dgp-39794\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεκμήραντο</h1><div class=\"entry-meta\"><span>DGP · ordem 336 na letra τ · nº geral 39794</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl., τεκμήρατο 3ª sing., do aor. méd. poét. de τεκμαίρω.</p></section></article>\n<article id=\"entry-dgp-39795\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεκμήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 337 na letra τ · nº geral 39795</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sinal de reconhecimento 2 Medic. indício; sintoma 3 testemunho; prova: τεκμήριον δὲ τούτου τόδε her. e a prova disso é esta, τεκμήριον δέ tuc. eis a prova, τ. ἀποδεικνύναι ou ἀποφαίνειν demonstrar com uma prova 4 Lóg. prova decisiva. 〈τέκμαρ〉</p></section></article>\n<article id=\"entry-dgp-39796\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεκμηριόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 338 na letra τ · nº geral 39796</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dar uma prova; provar; testemunhar ♦ méd. 2 inferir a partir de um sinal; supor; concluir. 〈τεκμήριον〉</p></section></article>\n<article id=\"entry-dgp-39797\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεκμηριώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 339 na letra τ · nº geral 39797</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">formulado com base em indícios; indutivo (entimema). 〈τεκμήριον, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-39798\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέκμωρ</h1><div class=\"entry-meta\"><span>DGP · ordem 340 na letra τ · nº geral 39798</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indecl. (τό) = τέκμαρ.</p></section></article>\n<article id=\"entry-dgp-39799\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεκνίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 341 na letra τ · nº geral 39799</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de τέκνον.</p></section></article>\n<article id=\"entry-dgp-39800\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεκνογονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 342 na letra τ · nº geral 39800</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter filhos. 〈τεκνογόνος〉</p></section></article>\n";
